<article class="card border-0 shadow-sm report-sheet"><div class="card-body p-4 p-md-5"><div class="d-flex justify-content-between border-bottom pb-3 mb-4"><div><h1 class="h3 mb-1"><?= e($azienda['ragione_sociale']) ?></h1><p class="small text-secondary mb-0"><?= e($azienda['indirizzo']??'') ?> <?= e($azienda['cap']??'') ?> <?= e($azienda['citta']??'') ?> · <?= e($azienda['partita_iva']??'') ?></p></div><div class="text-end"><strong>Rapporto intervento</strong><br><span>Numero <?= (int)$intervento['id'] ?></span></div></div><h2 class="h5">Cliente e luogo del servizio</h2><p><strong><?= e($intervento['cliente']) ?></strong><br><?= e($intervento['sede_nome']) ?> · <?= e(trim(($intervento['sede_indirizzo']??'').' '.($intervento['sede_citta']??''))) ?><br>Referente: <?= e($intervento['referente_nome']?:'—') ?> <?= e($intervento['referente_telefono']??'') ?></p><div class="row g-3 my-3"><div class="col-md-6"><strong>Servizio</strong><br><?= e(lbl($stati['servizio_tipo'],$intervento['tipo_servizio'])) ?></div><div class="col-md-6"><strong>Infestante</strong><br><?= e($intervento['infestante']?:'—') ?></div><div class="col-md-6"><strong>Data programmata</strong><br><?= e(fmt_data($intervento['pianificato_il'])) ?></div><div class="col-md-6"><strong>Operatori</strong><br><?= e(implode(', ',array_map(fn($o)=>$o['nome'].' '.$o['cognome'],$operatori))) ?></div><div class="col-md-6"><strong>Inizio effettivo</strong><br><?= e(fmt_data($intervento['inizio_effettivo'])) ?></div><div class="col-md-6"><strong>Fine effettiva</strong><br><?= e(fmt_data($intervento['fine_effettiva'])) ?></div></div><h2 class="h5 mt-4">Lavoro svolto ed esito</h2><p><?= nl2br(e($intervento['esito']?:'Non ancora registrato')) ?></p><h2 class="h5 mt-4">Materiali e prodotti</h2><?php if(!$materiali): ?><p>Nessun prodotto registrato.</p><?php else: ?><div class="table-responsive"><table class="table table-sm"><thead><tr><th>Prodotto</th><th>Lotto</th><th>Prelevato</th><th>Utilizzato</th><th>Restituito</th></tr></thead><tbody><?php foreach($materiali as $p): ?><tr><td><?= e($p['prodotto']) ?></td><td><?= e($p['lotto']?:'—') ?></td><td><?= e($p['quantita_prelevata'].' '.$p['unita_misura']) ?></td><td><?= e($p['quantita_utilizzata'].' '.$p['unita_misura']) ?></td><td><?= e($p['quantita_restituita'].' '.$p['unita_misura']) ?></td></tr><?php endforeach ?></tbody></table></div><?php endif ?><h2 class="h5 mt-4">Anomalie e note</h2><p><?= nl2br(e($intervento['note_operatore']?:'—')) ?></p><div class="row mt-5 pt-4"><div class="col-6"><p>Firma operatore</p><div class="border-bottom" style="height:50px"></div></div><div class="col-6"><p>Conferma referente cliente</p><div class="border-bottom" style="height:50px"></div></div></div><p class="small text-secondary mt-4">Documento generato il <?= e(date('d/m/Y H:i')) ?>. Allegati archiviati nel gestionale: <?= count($allegati) ?></p></div></article>
